function CreativeUniverseSection(){
 const worlds=[{name:'Writing',icon:'✍',focus:'Develop articles, campaign copy, brand messaging, and business content'},{name:'Images',icon:'◈',focus:'Generate visual concepts, product imagery, and branded creative assets'},{name:'Video',icon:'▶',focus:'Plan video content, develop promotional concepts, and explore AI-powered production'},{name:'Agents',icon:'✳',focus:'Explore AI assistants for customer engagement and repeatable business tasks'},{name:'Voice',icon:'◖',focus:'Develop narration, spoken content, and voice-enabled experiences'}];
 const [active,setActive]=useState<number|null>(null);
 const examplesRef=useRef<HTMLDivElement|null>(null);
 const [exampleSlide,setExampleSlide]=useState(0);
 const [examplePaused,setExamplePaused]=useState(false);
 const exampleGo=(index:number)=>{
  const track=examplesRef.current;
  if(!track)return;
  const cards=track.querySelectorAll<HTMLElement>('.cu-example-card');
  const next=(index+cards.length)%cards.length;
  if(!cards[next])return;
  track.scrollTo({left:cards[next].offsetLeft-cards[0].offsetLeft,behavior:'smooth'});
  setExampleSlide(next);
 };
 useEffect(()=>{
  if(examplePaused||typeof window==='undefined'||!window.matchMedia('(max-width:650px)').matches)return;
  const timer=window.setInterval(()=>exampleGo(exampleSlide+1),4500);
  return ()=>window.clearInterval(timer);
 },[exampleSlide,examplePaused]);

 return <section id="creative-universe" className="section creative-universe-section" aria-labelledby="creative-universe-heading"><div className="shell">
  <SectionEyebrow>SECTION 02 / FIVE CREATIVE WORLDS</SectionEyebrow>
  <div className="cu-intro"><h2 id="creative-universe-heading">One platform.<br/><span>More ways</span><br/>to create.</h2><p>Bring your ideas and workflows together with AI-powered writing, image creation, video production, voice, and intelligent agents. Xnovah is being built to make advanced tools more accessible, connected, and useful for everyday creative and business work.</p></div>
  <div className="cu-universe"><span className="cu-status">XNOVAH / UNIFIED AI CAPABILITIES</span><div className="cu-ring cu-ring-one"/><div className="cu-ring cu-ring-two"/><div className="cu-core" aria-hidden="true">✳</div>{worlds.map((w,i)=><button key={w.name} type="button" aria-pressed={active===i} onClick={()=>setActive(i)} className={'cu-orbit cu-orbit-'+(i+1)+(active===i?' selected':'')}>{w.icon} {w.name}</button>)}<span className="cu-hint">EXPLORE AN AI CAPABILITY ↗</span></div>
  <p className="cu-focus" aria-live="polite">{active===null?'Five core AI capabilities. One connected platform.':worlds[active].focus+' — explore this capability in the Xnovah ecosystem.'}</p>
  <div className="cu-journey" aria-label="Three stages of the Xnovah creative journey">
<div className="cu-journey-line" aria-hidden="true"><span/><span/><span/></div>
{[{n:'01',name:'IMAGINE',headline:'Define your objective.',desc:'Set a clear goal, describe your audience, and outline the result you want to achieve.',icon:Lightbulb,kind:'imagine'},{n:'02',name:'CREATE',headline:'Create with the right AI tools.',desc:'Use specialized AI capabilities to develop content, visuals, or workflows from your brief.',icon:WandSparkles,kind:'create'},{n:'03',name:'BUILD',headline:'Refine and prepare to deliver.',desc:'Review the output, make purposeful improvements, and prepare it for its intended use.',icon:Rocket,kind:'build'}].map((step,i)=>{const Icon=step.icon;return <motion.div {...floatIn} transition={{duration:.6,delay:i*.12}} className={'cu-journey-stage cu-journey-'+step.kind} key={step.n}>
<div className="cu-journey-scene" aria-hidden="true"><div className="cu-journey-orbit cu-journey-orbit-a"/><div className="cu-journey-orbit cu-journey-orbit-b"/><div className="cu-journey-aura"/><div className="cu-journey-illustration"><Icon size={62} strokeWidth={1.1}/><span className="cu-journey-star">✦</span></div><div className="cu-journey-float cu-journey-float-one">{i===0?'✧ YOUR BRIEF':i===1?'✳ AI TOOLS':'✦ RESULTS'}</div><div className="cu-journey-float cu-journey-float-two">{i===0?'DEFINE THE GOAL':i===1?'GENERATE · ITERATE':'READY FOR REVIEW'}</div></div>
<div className="cu-journey-copy"><span className="cu-journey-number">{step.n}</span><h3>{step.name}</h3><strong>{step.headline}</strong><p>{step.desc}</p></div></motion.div>})}
</div>


  <div id="experience" className="cu-journey-examples" aria-label="From imagination to creation workflow"><div className="cu-examples-heading"><span>FROM IMAGINATION TO CREATION</span><h3>Turn a clear vision into work that delivers.</h3><p>Every successful project starts with a purpose. Xnovah's envisioned workflow brings your brief, AI-powered production, and thoughtful refinement into a more connected process—helping you develop content and creative assets with greater clarity, consistency, and control.</p></div><div className="cu-examples-grid" ref={examplesRef} onTouchStart={()=>setExamplePaused(true)} onMouseEnter={()=>setExamplePaused(true)} onMouseLeave={()=>setExamplePaused(false)} onScroll={(e)=>{const track=e.currentTarget;const first=track.querySelector<HTMLElement>(".cu-example-card");if(first){const step=first.offsetWidth+14;setExampleSlide(Math.min(2,Math.max(0,Math.round(track.scrollLeft/step))))}}}>{[{step:'01 / IMAGINE',label:'DEFINE THE DIRECTION',example:'Set the objective, identify your audience, and describe the result you need. For example: “Develop a cohesive visual identity and launch campaign for a new product.”'},{step:'02 / CREATE',label:'PUT AI TO WORK',example:'Select the right capabilities for each deliverable—from campaign copy and product imagery to promotional video, narration, or supporting research.'},{step:'03 / BRING IT TO LIFE',label:'REFINE FOR REAL-WORLD USE',example:'Review accuracy, strengthen your brand voice, refine visuals, and prepare approved assets for publishing, presentation, or the next stage of your workflow.'}].map(item=><div className="cu-example-card" key={item.step}><span>{item.step}</span><small>{item.label}</small><strong>{item.example}</strong></div>)}</div><div className="cu-slider-controls" aria-label="Creative workflow slide indicators"><div className="cu-slider-dots">{[0,1,2].map(i=><button type="button" key={i} aria-label={'Show card '+(i+1)} aria-current={exampleSlide===i?'true':undefined} className={exampleSlide===i?'active':''} onClick={()=>{setExamplePaused(true);exampleGo(i)}} />)}</div></div></div>
  <div className="cu-footer"><span>✳ XNOVAH AI — Creative tools and intelligent workflows, connected.</span><a href="#feature-universe">UP NEXT / SECTION 03 — 39 AI FEATURES ↗</a></div>
 </div></section>
}


