function ToolDemo({toolName}:{toolName:string}){const demo=demoExperiences.find(d=>d.name===toolName);const [prompt,setPrompt]=useState('');const [style,setStyle]=useState('');const [shown,setShown]=useState(false);useEffect(()=>{setPrompt(demo?.prompt||'');setStyle(demo?.options[0]||'');setShown(false)},[toolName]);if(!demo)return null;return <div className="xcmd-demo" aria-label={toolName+' interactive concept demonstration'}><div className="xcmd-demo-heading"><strong>✦ TRY A GUIDED DEMO</strong><span>SIMULATED EXAMPLE · NO AI REQUEST</span></div><label htmlFor="xcmd-demo-prompt">Your creative brief</label><textarea id="xcmd-demo-prompt" value={prompt} onChange={e=>{setPrompt(e.target.value);setShown(false)}} rows={3} maxLength={500}/><label htmlFor="xcmd-demo-style">Creative direction</label><select id="xcmd-demo-style" value={style} onChange={e=>{setStyle(e.target.value);setShown(false)}}>{demo.options.map(o=><option key={o}>{o}</option>)}</select><button type="button" disabled={!prompt.trim()} onClick={()=>setShown(true)}>Preview example <ArrowUpRight size={15}/></button>{shown&&<div className="xcmd-demo-result" role="status"><small>ILLUSTRATIVE OUTPUT · {style.toUpperCase()}</small><p>{demo.output}</p><span>Example only. Your prompt was not sent to an AI model.</span></div>}</div>}
function ToolPreviewImage({toolName}:{toolName:string}){const [failed,setFailed]=useState(false);const [open,setOpen]=useState(false);useEffect(()=>{setFailed(false);setOpen(false)},[toolName]);useEffect(()=>{if(!open)return;const prev=document.body.style.overflow;document.body.style.overflow='hidden';const key=(e:KeyboardEvent)=>{if(e.key==='Escape')setOpen(false)};document.addEventListener('keydown',key);return()=>{document.body.style.overflow=prev;document.removeEventListener('keydown',key)}},[open]);const slug=toolName.replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-|-$/g,'');const src=`/images/${slug}.webp`;return <><div className="xcmd-agent-art xcmd-agent-image">{failed?<div className="xcmd-image-fallback"><span>✳</span><strong>{toolName}</strong><small>VISUAL PREVIEW COMING SOON</small></div>:<button type="button" className="xcmd-preview-tap" aria-label={`Enlarge ${toolName} image`} onClick={()=>setOpen(true)}><Image key={toolName} src={src} alt={`${toolName} — Xnovah AI workspace concept preview`} width={960} height={640} sizes="(max-width: 750px) 480px, (max-width: 1150px) 640px, 800px" quality={65} loading="lazy" onError={()=>setFailed(true)}/></button>}</div>{open&&!failed&&typeof document!=='undefined'&&createPortal(<div className="xcmd-preview-overlay" role="dialog" aria-modal="true" aria-label={`Enlarged ${toolName} image`} onClick={()=>setOpen(false)}><button type="button" className="xcmd-preview-dismiss" aria-label="Close enlarged image" autoFocus onClick={()=>setOpen(false)}>×</button><button type="button" className="xcmd-preview-full" aria-label="Close enlarged image" onClick={()=>setOpen(false)}><Image src={src} alt={`${toolName} enlarged — tap to close`} width={1440} height={960} sizes="100vw" quality={75} priority/><span>Tap image to close</span></button></div>,document.body)}</>}
function XnovahGuide(){const [open,setOpen]=useState(false),[question,setQuestion]=useState(''),[answer,setAnswer]=useState(''),[busy,setBusy]=useState(false);async function ask(e:React.FormEvent){e.preventDefault();if(!question.trim()||busy)return;setBusy(true);try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:question})});const data=await r.json();setAnswer(r.ok?data.answer:data.error||'Assistant unavailable')}catch{setAnswer('Assistant unavailable')}finally{setBusy(false)}}return <div className="xguide"><button type="button" className="xguide-trigger" onClick={()=>setOpen(!open)} aria-expanded={open} aria-controls="xguide-panel">{open?'Close guide':'Ask Xnovah'}</button>{open&&<section id="xguide-panel" className="xguide-panel" aria-label="Xnovah assistant"><strong>Xnovah Guide</strong><p>Ask about planned Xnovah tools and early access.</p><form onSubmit={ask}><label htmlFor="xguide-input">Your question</label><textarea id="xguide-input" value={question} onChange={e=>setQuestion(e.target.value)} maxLength={1000} rows={3}/><button type="submit" disabled={busy||!question.trim()}>{busy?'Thinking...':'Ask question'}</button></form><p role="status" aria-live="polite">{answer||'AI answers may be inaccurate. Xnovah is in development.'}</p><a href="#waitlist" onClick={()=>setOpen(false)}>Early access</a></section>}</div>}
