 'LinkedIn':'#087dbb','Google Drive':'#ffffff','Google Calendar':'#ffffff',
 'Slack':'#ffffff','Webflow':'#1769ff','Blogger':'#ff671d','Medium':'#121212',
 'WordPress':'#1676ae','HubSpot':'#ff6b3d','WooCommerce':'#96588a',
