function DedicatedShowcases(){const [selected,setSelected]=useState<number|null>(null);return <div className="dedicated-wrap" id="tools"><div className="shell"><div className="dedicated-intro"><SectionEyebrow>EXPLORE YOUR CREATIVE UNIVERSE</SectionEyebrow><h2>Every possibility deserves <span className="gradient-text">its own spotlight.</span></h2><p>Discover the individual creative experiences we're exploring for Xnovah. Each showcase is a concept preview, not a live AI generation tool.</p></div></div>{dedicatedFeatures.map((item,index)=><section className={'dedicated-section dedicated-theme-'+index%4+(/video|ugc/i.test(item.name+' '+item.title)?' xnovah-crimson-media':'')} id={'tool-'+index} key={item.name}><div className="shell dedicated-grid"><div className="dedicated-copy"><span className="dedicated-number">XNOVAH / {String(index+1).padStart(2,'0')} — CREATIVE CAPABILITIES</span><h2>{item.title}</h2><p>{item.description}</p><div className="dedicated-label">{item.name}</div><div className="dedicated-steps">{item.steps.split(' · ').map(step=><span key={step}>{step}</span>)}</div><div className="dedicated-actions"><button type="button" className="button-ghost dedicated-preview-btn" onClick={()=>setSelected(selected===index?null:index)} aria-expanded={selected===index}>{selected===index?'Hide preview':'Explore concept'} <ArrowUpRight size={16}/></button><a href="#waitlist" className="dedicated-link">Get early access ↗</a></div>{selected===index&&<div className="dedicated-detail"><b>Experience concept</b><p>{item.sample} This is a visual illustration; no AI request is being made.</p></div>}</div><div className="dedicated-visual" aria-label={item.name+' concept illustration'}><div className="dedicated-visual-grid"/><div className="dedicated-visual-orb"/><div className="dedicated-glass-card"><span className="dedicated-card-top"><span>✳ XNOVAH STUDIO</span><span>CONCEPT / {String(index+1).padStart(2,'0')}</span></span><div className="dedicated-card-icon">✦</div><span className="dedicated-card-type">{item.name.toUpperCase()}</span><strong>{item.sample}</strong><div className="dedicated-card-bottom"><span>✧ CREATIVE MODE</span><span>↗</span></div></div><span className="dedicated-visual-caption">IMAGINE MORE / CREATE BEYOND</span></div></div></section>)}</div>}
